import Model from 'flarum/common/Model';
/** A comment on an item, optionally in reply to one of its reviews (MyBB product comments). */
export default class Comment extends Model {
  body = Model.attribute('body');
  bodyHtml = Model.attribute('bodyHtml');
  reviewId = Model.attribute('reviewId');
  replyToName = Model.attribute('replyToName');
  isOfficial = Model.attribute('isOfficial');
  itemPath = Model.attribute('itemPath');
  itemName = Model.attribute('itemName');
  createdAt = Model.attribute('createdAt', Model.transformDate);
  editedAt = Model.attribute('editedAt', Model.transformDate);
  canEdit = Model.attribute('canEdit');
  canDelete = Model.attribute('canDelete');
  canReport = Model.attribute('canReport');
  item = Model.hasOne('item');
  user = Model.hasOne('user');
}
flarum.reg.add('ernestdefoe-community-reviews', 'forum/models/Comment', Comment);