import Model from 'flarum/common/Model';
/** A review category (MyBB "category") with its criteria (MyBB "fields"). */
export default class Category extends Model {
  name = Model.attribute('name');
  slug = Model.attribute('slug');
  description = Model.attribute('description');
  icon = Model.attribute('icon');
  color = Model.attribute('color');
  position = Model.attribute('position');
  parentId = Model.attribute('parentId');
  itemFields = Model.attribute('itemFields');
  itemCount = Model.attribute('itemCount');
  reviewCount = Model.attribute('reviewCount');
  criteria = Model.hasMany('criteria');
}
flarum.reg.add('ernestdefoe-community-reviews', 'forum/models/Category', Category);