import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
import humanTime from 'flarum/common/helpers/humanTime';
import username from 'flarum/common/helpers/username';
import { setting, t } from './util';

/** The index widget: the newest reviews, compact (the admin's widget length), in forum.js so it needs no chunk. */
export default class LatestReviews extends Component {
  reviews = [];
  oninit(vnode) {
    super.oninit(vnode);
    app.store.find('reviews', {
      include: 'user',
      page: {
        limit: Number(setting('widget_limit')),
        total: 0
      }
    }).then(list => this.reviews = [...list]).catch(() => {
      /* the widget simply stays empty; the discussion list above it is what the page is for */
    }).finally(() => m.redraw());
  }
  view() {
    if (!this.reviews.length) return null;
    return m("section", {
      className: "CR-widget"
    }, m("header", {
      className: "CR-widget-head"
    }, m("h3", null, t('widget.title')), m(Link, {
      href: app.route('community-reviews.index')
    }, t('widget.all'))), m("ul", null, this.reviews.map(review => m("li", null, m(Link, {
      href: app.route('community-reviews.item', {
        id: review.itemPath() || ''
      }) + `#review${review.id()}`
    }, m("span", {
      className: "CR-widget-score"
    }, review.rating().toFixed(1)), m("span", {
      className: "CR-widget-name"
    }, review.itemName()), m("span", {
      className: "CR-muted"
    }, username(review.user() || null), " \xB7 ", humanTime(review.createdAt())))))));
  }
}