import Model from 'flarum/common/Model';
/** A member's report of an item, review or comment, for the moderators' queue. */
export default class Report extends Model {
  subjectType = Model.attribute('subjectType');
  subjectId = Model.attribute('subjectId');
  reason = Model.attribute('reason');
  excerpt = Model.attribute('excerpt');
  resolved = Model.attribute('resolved');
  createdAt = Model.attribute('createdAt', Model.transformDate);
  item = Model.hasOne('item');
  user = Model.hasOne('user');
}
flarum.reg.add('ernestdefoe-community-reviews', 'forum/models/Report', Report);