import Model from 'flarum/common/Model';
/** A member's review: a score and comment per criterion, General thoughts, price, link, merchant, photos. */
export default class Review extends Model {
  rating = Model.attribute('rating');
  previousRating = Model.attribute('previousRating');
  title = Model.attribute('title');
  body = Model.attribute('body');
  bodyHtml = Model.attribute('bodyHtml');
  scores = Model.attribute('scores');
  price = Model.attribute('price');
  url = Model.attribute('url');
  photos = Model.attribute('photos');
  ownedFor = Model.attribute('ownedFor');
  pros = Model.attribute('pros');
  cons = Model.attribute('cons');
  isVerified = Model.attribute('isVerified');
  status = Model.attribute('status');
  helpfulCount = Model.attribute('helpfulCount');
  votedHelpful = Model.attribute('votedHelpful');
  commentCount = Model.attribute('commentCount');
  itemPath = Model.attribute('itemPath');
  itemName = Model.attribute('itemName');
  createdAt = Model.attribute('createdAt', Model.transformDate);
  editedAt = Model.attribute('editedAt', Model.transformDate);
  canEdit = Model.attribute('canEdit');
  canDelete = Model.attribute('canDelete');
  canModerate = Model.attribute('canModerate');
  canVote = Model.attribute('canVote');
  canReport = Model.attribute('canReport');
  item = Model.hasOne('item');
  user = Model.hasOne('user');
  merchant = Model.hasOne('merchant');
}
flarum.reg.add('ernestdefoe-community-reviews', 'forum/models/Review', Review);